{"packet_id":"D040-01","doc_id":"D040","jurisdiction":"Los Angeles, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Los Angeles Just Cause for Eviction Ordinance (JCO)","requirement":"Landlords may not end a tenancy without just cause and must provide relocation assistance for no-fault evictions. A tenancy is covered once the tenant has lived in the unit six months or the original lease has expired.","key_value":null,"coverage_conditions":"Most residential properties in the City of Los Angeles not regulated by the RSO, once the tenant has lived in the unit six months or the lease expired; can apply to buildings newer than October 1, 1978 and single-family dwellings.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":true,"other":"Covers residential units not regulated by the City's RSO; no building-age cutoff."},"exemptions":"Transient hotels, licensed care facilities, fraternity or sorority houses, owner's roommate, certain cooperatives, some non-profit facilities for the homeless or short-term substance-abuse treatment centers, and some properties owned by HACLA or the government.","penalty":null,"effective_date":null,"citation":"Los Angeles Just Cause Ordinance (L.A.M.C. §165.00 et seq.)","quoted_span":"It prohibits terminations of tenancies without just cause and requires relocation assistance for no-fault evictions.","interaction":"Covers residential properties not regulated by the City's Rent Stabilization Ordinance (RSO).","confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D040-01","doc_id":"D040","jurisdiction":"CA","category":"rent_increase_limits","lifecycle":"enacted","title":"California Tenant Protection Act (AB 1482) rent cap","requirement":"Annual rent increases for covered units are limited to 5% plus the regional cost-of-living change, or 10%, whichever is lower. From August 1, 2024 to July 31, 2025 the maximum allowable increase was 8.9%.","key_value":"5% + regional CPI, max 10%; 8.9% (Aug 1, 2024 to Jul 31, 2025)","coverage_conditions":"Units more than 15 years old, on a rolling basis. Excludes units built within the last 15 years, deed- or regulatory-restricted affordable units, certain dormitories, owner-occupied two-unit properties, and units subject to the City's RSO.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":"construction_date","min_units":null,"max_units":null,"owner_dependent":true,"other":"Covered only if the unit was constructed more than 15 years ago, applied on a rolling basis."},"exemptions":"Units built within the last 15 years; deed- or regulatory-restricted affordable units; certain dormitories; owner-occupied two-unit properties; single-family homes and condominiums not owned by a corporate entity where required notice was given; units subject to the City's RSO.","penalty":null,"effective_date":"2024-08-01","citation":"Cal. Civ. Code § 1947.12","quoted_span":"Effective August 1, 2024 to July 31, 2025, the maximum allowable increase is 8.9%.","interaction":"The JCO does not regulate rent increases; this state law may regulate rent in units not covered by the City's RSO.","confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D040-01","doc_id":"D040","jurisdiction":"Los Angeles, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Los Angeles non-payment of rent eviction threshold","requirement":"Landlords may not evict a tenant who falls behind in rent unless the amount owed is higher than the Fair Market Rent for the unit's bedroom size.","key_value":"Rent owed must exceed the FMR for the unit's bedroom size","coverage_conditions":"Applies to all RSO and JCO rental units in the City of Los Angeles.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"Applies to all RSO and JCO rental units."},"exemptions":null,"penalty":null,"effective_date":"2023-03-27","citation":"Los Angeles Evictions for Non-Payment of Rent","quoted_span":"Effective March 27, 2023, landlords may not evict a tenant who falls behind in rent unless the tenant owes an amount higher than the Fair Market Rent (FMR).","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
